import { useState, useEffect, useRef } from 'react';
import { Store, LayoutDashboard, Package, ShoppingBag, Wallet, ChartNoAxesCombined, Settings, Bell, ChevronDown, ChevronRight, ArrowUpRight, ArrowDownLeft, Plus, Search, Download, X, Check, ArrowRight, CircleHelp, TrendingUp, TrendingDown, MoreHorizontal, Pencil, RefreshCw, Trash2, CheckCircle2, AlertCircle, ReceiptText, CreditCard, Banknote, Landmark, Minus, Menu, Sprout, ShieldCheck, ExternalLink, Printer, CalendarDays, LoaderCircle, Boxes, ArrowUpDown } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, PieChart, Pie, Cell } from 'recharts';
