      <div className="workspace-card"><span className="workspace-avatar">{data.settings.name.slice(0, 1).toUpperCase()}</span><div><b>{data.settings.name}</b><small>Ruang usaha kamu</small></div><button className="icon-button" aria-label="Ubah nama warung" onClick={() => navigate('settings')}><ChevronDown size={15} /></button></div>
